import math


@dataclass(frozen=True)
class Trazione:
    N: float


@dataclass(frozen=True)
class Flessione:
    M: float
    W: float


@dataclass(frozen=True)
class Taglio:
    V: float
    Av: float


def tensione_ideale(carico, A):
    match carico:
        case Trazione(N=N):
            return N / A
        case Flessione(M=M, W=W):
            return M / W
        case Taglio(V=V, Av=Av):
            return math.sqrt(3) * V / Av
        case _:
            raise TypeError(f"carico non riconosciuto: {carico!r}")
